  ('734604ea-7bbc-493b-8ec6-ef1277d71e7c', 'd0e1f2a3-4b5c-4d18-9e78-8f9a0b1c2d08', null, 'topic'::public.curated_course_node_type, 'What Metaphysics Studies: Being, Reality, and Philosophical Method', 'Introduce metaphysics as the disciplined study of what exists and what reality is like at the most general level.', 0),
  ('2f467122-8937-487e-8d90-c5a5e0bb276d', 'd0e1f2a3-4b5c-4d18-9e78-8f9a0b1c2d08', '734604ea-7bbc-493b-8ec6-ef1277d71e7c', 'subtopic'::public.curated_course_node_type, 'The scope of metaphysics', 'Why it matters: Students learn why metaphysics asks unusually general questions about reality rather than questions about one local domain.', 0),
