update public.learning_paths
set
  title = 'Metaphysics',
  goal = 'Metaphysics',
  summary = 'Students explain major metaphysical questions about existence, identity, modality, causation, time, objects, mind, and freedom; reconstruct and evaluate classic and contemporary arguments with precision and charity; compare realist, nominalist, reductionist, anti-reductionist, Humean, and non-Humean theories; use logical and modal vocabulary to clarify ontological commitments and possible-worlds reasoning; connect metaphysics to science, mind, social categories, religion, ethics, and ordinary life; and produce a polished research paper with a clear thesis, objections, replies, and source-based argument.',
  data = $metajson${"slug": "metaphysics", "title": "Metaphysics", "description": "Students explain major metaphysical questions about existence, identity, modality, causation, time, objects, mind, and freedom; reconstruct and evaluate classic and contemporary arguments with precision and charity; compare realist, nominalist, reductionist, anti-reductionist, Humean, and non-Humean theories; use logical and modal vocabulary to clarify ontological commitments and possible-worlds reasoning; connect metaphysics to science, mind, social categories, religion, ethics, and ordinary life; and produce a polished research paper with a clear thesis, objections, replies, and source-based argument.", "topics": [{"id": "734604ea-7bbc-493b-8ec6-ef1277d71e7c", "type": "topic", "title": "What Metaphysics Studies: Being, Reality, and Philosophical Method", "description": "Introduce metaphysics as the disciplined study of what exists and what reality is like at the most general level.", "children": [{"id": "2f467122-8937-487e-8d90-c5a5e0bb276d", "type": "subtopic", "title": "The scope of metaphysics", "children": [{"id": "831b78c6-8767-4f4c-9d03-96180a55d782", "type": "concept", "title": "Being as such"}, {"id": "c06f27d7-b8e2-43b9-9dd1-6e02e8b84ee5", "type": "concept", "title": "Categories of reality"}, {"id": "2882b1bc-b722-4cb8-8c1c-885edfebfe2b", "type": "concept", "title": "Abstract and concrete entities"}, {"id": "e3e3d682-1ec9-44bd-9993-e6ee723bef5e", "type": "concept", "title": "Ordinary versus fundamental description"}], "description": "Why it matters: Students learn why metaphysics asks unusually general questions about reality rather than questions about one local domain."}, {"id": "d76e51d9-b620-4edf-8051-bf77ad7cc7f2", "type": "subtopic", "title": "Metaphysical questions", "children": [{"id": "41a81579-e716-4f18-b65c-ffa0e4001cdb", "type": "concept", "title": "What exists?"}, {"id": "899641c3-e1d6-4eb2-a9ed-e36c4ae43e0c", "type": "concept", "title": "What is fundamental?"}, {"id": "007cdec0-71a3-4a81-b4b5-c709f55dbde1", "type": "concept", "title": "What explains what?"}, {"id": "b6ce3b4d-edd8-48a8-be63-8d77aa359747", "type": "concept", "title": "What could have been otherwise?"}], "description": "Why it matters: The course begins by making classic questions precise enough to argue about."}, {"id": "f1d1e052-77f3-4a9e-85bb-0389414a410c", "type": "subtopic", "title": "Method and disagreement", "children": [{"id": "6094de5a-ec1c-49ea-8d4b-9fff8aa053d5", "type": "concept", "title": "Conceptual analysis"}, {"id": "0281f74a-8a56-4aa5-9200-359f6ef3ab53", "type": "concept", "title": "Inference to best explanation"}, {"id": "e02caa1a-cd43-4c48-8432-df7e2ed100a2", "type": "concept", "title": "Thought experiments"}, {"id": "bf3051d0-dc5f-43e1-a95f-6c510a1ea9c0", "type": "concept", "title": "Theoretical virtues"}], "description": "Why it matters: Metaphysics depends on argument, analysis, cases, science, and theory choice rather than simple observation alone."}]}, {"id": "a2550a0e-28df-4c12-988f-7b8b56588699", "type": "topic", "title": "Existence, Being, Ontological Commitment, and Quantification", "description": "Learn how philosophers ask what there is and what a theory commits us to accepting.", "children": [{"id": "8cf035f8-a187-4592-aa68-68e09403238a", "type": "subtopic", "title": "Existence questions", "children": [{"id": "5171cdf8-b5e6-409d-853c-d364b6947774", "type": "concept", "title": "Concrete objects"}, {"id": "5b610724-159e-44b5-af3a-39057c3fdb2d", "type": "concept", "title": "Abstract objects"}, {"id": "678101c2-0ea1-4744-8668-7a948f6d3075", "type": "concept", "title": "Fictional entities"}, {"id": "ff24daa7-45a6-4d67-a4b6-2454ffd2457a", "type": "concept", "title": "Negative existentials"}], "description": "Why it matters: Students learn to distinguish asking whether something exists from asking what it is like."}, {"id": "66cb5cae-351b-428b-bf75-938c19604799", "type": "subtopic", "title": "Ontological commitment", "children": [{"id": "cbe42996-9684-4343-94ca-66e32f5b3bba", "type": "concept", "title": "Quine's criterion"}, {"id": "1a40fe47-aaa4-4015-9641-b8dcc3d9f744", "type": "concept", "title": "Quantifiers"}, {"id": "c582811b-f195-4a7f-aa7f-8ea7887ce4e8", "type": "concept", "title": "Paraphrase strategies"}, {"id": "7d0315e1-70c7-41de-aa6c-d3357b8a1a31", "type": "concept", "title": "Ontological economy"}], "description": "Why it matters: A theory's commitments are the entities it must count as real to make its claims true."}, {"id": "1171996c-21cb-4019-b7a7-0b7f7f537b60", "type": "subtopic", "title": "Metaontology", "children": [{"id": "a73f55b4-88c1-4ce9-b655-5978ffbeffae", "type": "concept", "title": "Carnapian frameworks"}, {"id": "152592d6-2446-44de-9d51-70ee2c935452", "type": "concept", "title": "Realism about ontology"}, {"id": "50b29977-b9ab-4887-aae9-b1cad2199204", "type": "concept", "title": "Deflationary approaches"}, {"id": "f6770f2a-f47c-4dc5-b963-5ed04c097e6b", "type": "concept", "title": "Methodological disagreement"}], "description": "Why it matters: Students consider whether ontological disputes are deep, verbal, pragmatic, or framework-relative."}]}, {"id": "cc665dd0-0032-4b75-967e-677b34bb68bf", "type": "topic", "title": "Universals, Particulars, Properties, Tropes, and Resemblance", "description": "Examine whether things share real properties or only resemble one another in patterns we describe.", "children": [{"id": "c08f0436-8286-4e2b-b1be-1ce34c36e933", "type": "subtopic", "title": "The problem of universals", "children": [{"id": "c634accc-22c5-4c1d-a61f-93101cd7d6f7", "type": "concept", "title": "One-over-many problem"}, {"id": "597715ab-3148-4d6d-8213-8ec09057d1cb", "type": "concept", "title": "Predication"}, {"id": "fed06593-2878-450e-906d-34b8c55963e2", "type": "concept", "title": "Repeatable properties"}, {"id": "ec08cae1-4514-4e0e-a4fe-dc513007b3c1", "type": "concept", "title": "Abstract objects"}], "description": "Why it matters: The point is to explain how many distinct things can be alike in the same respect."}, {"id": "a02d75cd-7a3c-4e58-84ff-676d6007a867", "type": "subtopic", "title": "Realist and nominalist theories", "children": [{"id": "1f566884-1ac6-4372-b9e7-b1a7f40b0d84", "type": "concept", "title": "Platonic realism"}, {"id": "c168c592-621e-4d13-ada1-c75fcca2184c", "type": "concept", "title": "Aristotelian realism"}, {"id": "477755a4-8fc6-4b58-9f68-447a288cd3e3", "type": "concept", "title": "Nominalism"}, {"id": "6b052ba0-219e-432b-b110-7e6e1c9f6708", "type": "concept", "title": "Class and resemblance theories"}], "description": "Why it matters: Students compare the costs of admitting universals with the costs of explaining resemblance without them."}, {"id": "77b2fe1a-2f02-42a7-87fb-276de48b8bf7", "type": "subtopic", "title": "Tropes and property instances", "children": [{"id": "94071823-6f84-4e25-b222-11d0a6015a15", "type": "concept", "title": "Tropes"}, {"id": "5d596a14-3a81-4f8d-8340-71ebd18b80c9", "type": "concept", "title": "Bundles"}, {"id": "9f664f03-569b-4fbb-9d1a-2d717d2166a6", "type": "concept", "title": "Compresence"}, {"id": "0e58d31f-8fee-43a0-a107-dcce8df69773", "type": "concept", "title": "Resemblance classes"}], "description": "Why it matters: Trope theory treats properties as particularized features rather than repeatable universals."}]}, {"id": "4966dce9-2af5-4a14-a504-fb292676e9c8", "type": "topic", "title": "Substance, Essence, Kinds, and Grounding", "description": "Study what makes a thing the kind of thing it is and what explains facts at the deepest level.", "children": [{"id": "38261d07-2e3c-4ee6-b3ea-4b681ebd05a1", "type": "subtopic", "title": "Substance and independence", "children": [{"id": "c94f0139-4443-4197-b609-8a0e9d23490d", "type": "concept", "title": "Aristotelian substance"}, {"id": "84ec56ea-2574-4712-8713-6b5b586246a3", "type": "concept", "title": "Independence"}, {"id": "a15f07f6-66c7-4813-87a1-13a198560c6b", "type": "concept", "title": "Substratum theories"}, {"id": "4c8062ac-1057-4314-a56b-0312002f0eae", "type": "concept", "title": "Bundle theories"}], "description": "Why it matters: Substance theories ask what exists in its own right rather than as a feature of something else."}, {"id": "d6d3df60-9162-4775-b5b3-7153824c66fc", "type": "subtopic", "title": "Essence and kinds", "children": [{"id": "a042a26c-619c-43b7-b99d-2a81c81cd665", "type": "concept", "title": "Essential properties"}, {"id": "d76c7412-e86f-4288-beda-b732ec148135", "type": "concept", "title": "Accidental properties"}, {"id": "21f813dc-bf88-4a41-bb27-5fcb9c64e0d9", "type": "concept", "title": "Natural kinds"}, {"id": "54a4b436-73d1-4527-8154-bbdd4677e954", "type": "concept", "title": "Real definitions"}], "description": "Why it matters: Essence explains what a thing is, not merely what happens to be true of it."}, {"id": "93c5e4a4-9d26-436a-9fdf-228685949cee", "type": "subtopic", "title": "Grounding and fundamentality", "children": [{"id": "878562bc-5de7-408b-a8aa-1b53ff6f1923", "type": "concept", "title": "Grounding relations"}, {"id": "53b749aa-a77d-406f-9498-f49d299dc07b", "type": "concept", "title": "Fundamental facts"}, {"id": "8a8b515d-1944-44e4-a626-ea2f1324a33b", "type": "concept", "title": "Dependence"}, {"id": "33e957e2-e514-46f5-9b17-b6d770ee4fa0", "type": "concept", "title": "Metaphysical explanation"}], "description": "Why it matters: Grounding is a contemporary way to ask what explains what at the deepest metaphysical level."}]}, {"id": "d6c358fd-0014-48b8-9915-5a825cb11576", "type": "topic", "title": "Modality, Necessity, Possibility, and Possible Worlds", "description": "Analyze what could have been otherwise, what must be true, and how modal claims are grounded.", "children": [{"id": "3931d905-ea17-4e9b-b363-448ecb70ad02", "type": "subtopic", "title": "Modal concepts", "children": [{"id": "3887fcca-8b26-49f4-b7d1-506273247eff", "type": "concept", "title": "Logical necessity"}, {"id": "2c248d0f-5c41-4688-a7d7-4685816947fe", "type": "concept", "title": "Metaphysical necessity"}, {"id": "1e9ed926-894a-4f39-b7ea-eefacc858609", "type": "concept", "title": "Physical necessity"}, {"id": "836c4a21-9ad7-4748-b922-1818708a4ad1", "type": "concept", "title": "Epistemic possibility"}], "description": "Why it matters: Students learn to reason carefully about necessity, possibility, contingency, and impossibility."}, {"id": "3a0498a4-9d18-45aa-ae38-cf81c4a300a6", "type": "subtopic", "title": "Possible worlds", "children": [{"id": "5fa18291-338a-47df-9eb1-5bfe35f6c90f", "type": "concept", "title": "Actualism"}, {"id": "4e210560-fd7a-4828-a58b-e5b8e29413c1", "type": "concept", "title": "Modal realism"}, {"id": "c084558e-ce26-4ab3-88c1-1215732af171", "type": "concept", "title": "World-stories"}, {"id": "c00867c8-6590-4003-ba8b-a3f142b3bc90", "type": "concept", "title": "Accessibility relations"}], "description": "Why it matters: Possible-worlds talk gives structure to claims about what could or must be true."}, {"id": "10d9f298-ca65-40a3-8e8c-a11398b894b5", "type": "subtopic", "title": "Modal epistemology", "children": [{"id": "4595c02b-7e68-471e-a2d9-cafb54b779c4", "type": "concept", "title": "Conceivability"}, {"id": "f767da18-cd29-4367-bfaa-7ec0362f378a", "type": "concept", "title": "Counterexamples"}, {"id": "9710c8c7-1791-4d13-a625-46797b0a3c2c", "type": "concept", "title": "Essence-based modality"}, {"id": "6bde324a-8692-405b-bf01-2b4aeaaf607e", "type": "concept", "title": "Scientific constraints"}], "description": "Why it matters: Students ask how we know modal truths if they are not simply observed."}]}, {"id": "a85520ca-08ef-430b-a701-eafafc4d1b18", "type": "topic", "title": "Identity, Indiscernibility, Individuation, and Persistence", "description": "Investigate what makes something the same thing across change, time, and description.", "children": [{"id": "e473b301-f2b8-491a-8845-d4e278114ed3", "type": "subtopic", "title": "Identity principles", "children": [{"id": "535b0c41-c31e-4433-946f-88cc9f27e211", "type": "concept", "title": "Reflexivity"}, {"id": "2c0b6257-ed7b-4aa7-ab68-dba0228bc27b", "type": "concept", "title": "Symmetry and transitivity"}, {"id": "fde47b3f-ca99-4a77-a1e7-8ac208ad5564", "type": "concept", "title": "Leibniz's Law"}, {"id": "f95e5d80-a3f2-4d1c-b761-512d5ebff858", "type": "concept", "title": "Indiscernibility of identicals"}], "description": "Why it matters: Identity is strict sameness, and students learn the logical rules governing it."}, {"id": "22e81a6c-2e3b-49aa-a4da-f2ed9c326273", "type": "subtopic", "title": "Individuation", "children": [{"id": "7c63c88f-2d64-4328-81e4-4a78bc059410", "type": "concept", "title": "Sortals"}, {"id": "a684d659-3ada-4af7-ae97-10a6e1104e59", "type": "concept", "title": "Haecceity"}, {"id": "c477e35d-d58f-454b-b9b2-d2ac9ec1cd88", "type": "concept", "title": "Qualitative identity"}, {"id": "a8dbf6c1-80b6-4c01-822e-2505572e7d4c", "type": "concept", "title": "Indiscernible duplicates"}], "description": "Why it matters: Individuation asks what makes one entity distinct from another."}, {"id": "6e96561c-b49a-489f-bf95-0349c34a6bc3", "type": "subtopic", "title": "Persistence through change", "children": [{"id": "bb53c65c-dd15-409e-a140-ab8c8bedb846", "type": "concept", "title": "Endurantism"}, {"id": "88723796-5a1e-46e8-a5c9-6745d598ef75", "type": "concept", "title": "Perdurantism"}, {"id": "6163b42d-8dc5-4bbe-9754-6dd7faa65fc7", "type": "concept", "title": "Stage theory"}, {"id": "dcaf0c02-b4a8-4190-b5fe-08ddf34ba9c0", "type": "concept", "title": "Temporary intrinsics"}], "description": "Why it matters: Students compare theories of how things remain the same while changing."}]}, {"id": "e1f836e8-55d3-4554-8e3c-a5560f6f6b23", "type": "topic", "title": "Time, Space, Temporal Passage, and Relativity-Aware Metaphysics", "description": "Compare theories of time and persistence while taking scientific accounts of spacetime seriously.", "children": [{"id": "8e6bf21d-a00b-4ac6-9ebb-0440b285f19e", "type": "subtopic", "title": "Theories of time", "children": [{"id": "db7d949d-f392-4c34-abc0-6a7366568c7e", "type": "concept", "title": "Presentism"}, {"id": "29ff4931-2098-44bc-9d28-724bd767ce0c", "type": "concept", "title": "Eternalism"}, {"id": "018fcbcf-21c5-4517-97c5-864750fd4332", "type": "concept", "title": "Growing block theory"}, {"id": "e253b266-6aeb-4029-b1e8-f7887d8b68d4", "type": "concept", "title": "Moving spotlight theory"}], "description": "Why it matters: Different theories disagree about whether only the present is real or past and future are equally real."}, {"id": "cad330d9-8d2d-4f83-8c93-e4851e942edd", "type": "subtopic", "title": "Temporal passage", "children": [{"id": "3b8f40b2-98e2-4bce-b16b-442a485917c0", "type": "concept", "title": "A-series and B-series"}, {"id": "f4907bcd-d72b-402a-a4fa-314a49181619", "type": "concept", "title": "Tensed facts"}, {"id": "c8a38cf4-266f-47c1-a9c8-b6bc5413a83a", "type": "concept", "title": "Indexicality"}, {"id": "b18b3391-5763-4613-b799-f4010dadd2fe", "type": "concept", "title": "Experience of passage"}], "description": "Why it matters: Students ask whether time really flows or whether passage is a feature of experience."}, {"id": "cf8a8f16-3d58-445a-855f-c8f84eb4c523", "type": "subtopic", "title": "Space and spacetime", "children": [{"id": "31a3bd94-c574-4562-ad7f-c7d17f41249a", "type": "concept", "title": "Substantivalism"}, {"id": "9e66235b-ebb7-41d6-bff3-4688bd2efd2d", "type": "concept", "title": "Relationism"}, {"id": "b4034b2d-0bde-4006-b117-f75c04d44277", "type": "concept", "title": "Special relativity"}, {"id": "70c6d051-d4eb-49be-8a54-41ff45a7e527", "type": "concept", "title": "Spacetime ontology"}], "description": "Why it matters: Metaphysics of time must engage with physics without collapsing into physics."}]}, {"id": "640b5f74-e130-4609-a746-bbf6f04f86f5", "type": "topic", "title": "Causation, Laws of Nature, Powers, and Explanation", "description": "Study what it means for one thing to cause another and how laws or powers structure reality.", "children": [{"id": "b4f542ba-8fa0-4f3f-86cc-b6b3dc14dbfb", "type": "subtopic", "title": "Causal relations", "children": [{"id": "d589f678-bf98-4843-9ce2-b33a60dc6ba5", "type": "concept", "title": "Regularity theories"}, {"id": "e16db73b-b3a8-4d72-bad5-af2d14325936", "type": "concept", "title": "Counterfactual theories"}, {"id": "f764026a-8358-4e2a-9209-f07eba7f958c", "type": "concept", "title": "Process theories"}, {"id": "5d7b5067-844e-4a0b-8806-fc46c1e53cb8", "type": "concept", "title": "Interventionist accounts"}], "description": "Why it matters: Causation connects events, objects, processes, and explanations, but its nature is contested."}, {"id": "806ffba8-066f-46d1-8b77-5dd7fbfb3d30", "type": "subtopic", "title": "Laws of nature", "children": [{"id": "c58b4338-b051-42cf-a859-adf80b771d7d", "type": "concept", "title": "Humean regularity"}, {"id": "d87c0a03-12ce-42f6-b299-aec69fc7c0a2", "type": "concept", "title": "Nomic necessity"}, {"id": "896924af-3578-41ca-8bff-7d996ac03ad5", "type": "concept", "title": "Best-system account"}, {"id": "8b0a2a5d-a2c5-4aaf-8b6c-60b659af4f0a", "type": "concept", "title": "Governing-law views"}], "description": "Why it matters: Students learn competing accounts of what makes laws more than accidental generalizations."}, {"id": "3507c16d-a895-484b-9291-ee70454adb63", "type": "subtopic", "title": "Powers and dispositions", "children": [{"id": "a98908f8-20b1-419d-a13a-d67179a3cae5", "type": "concept", "title": "Dispositions"}, {"id": "30a5f1cd-aa36-4229-85b4-818206f57d0d", "type": "concept", "title": "Manifestation conditions"}, {"id": "ed559659-c669-49b6-9f24-91b21ecad505", "type": "concept", "title": "Causal powers"}, {"id": "6bd492de-45c6-4891-a6b8-4eff1debd955", "type": "concept", "title": "Fragility and solubility examples"}], "description": "Why it matters: Power-based metaphysics treats objects as having real capacities that explain their behavior."}]}, {"id": "8da8e1fc-20f8-48d3-8314-3bd6b1e4ee29", "type": "topic", "title": "Material Objects, Composition, Parts, Wholes, and Boundaries", "description": "Ask when many things compose one thing and what ordinary objects really are.", "children": [{"id": "b81cadfd-a026-4f7f-a6e4-b95a3426e0a1", "type": "subtopic", "title": "The special composition question", "children": [{"id": "5d1cc2e7-4709-404c-83c6-0867d7d51141", "type": "concept", "title": "Mereology"}, {"id": "39919701-b596-4038-993d-97a98a1baa5a", "type": "concept", "title": "Universalism"}, {"id": "2d10e85a-78f6-4629-8b40-cbce02bf72ec", "type": "concept", "title": "Nihilism"}, {"id": "12fb0cab-66aa-408c-8872-81615c690496", "type": "concept", "title": "Restricted composition"}], "description": "Why it matters: Students ask when many things compose one thing rather than merely being many things."}, {"id": "1dc646bd-9f11-4724-9632-a501b51e5471", "type": "subtopic", "title": "Ordinary objects", "children": [{"id": "9c9b05de-dfcb-4477-9551-81ed5dc1b041", "type": "concept", "title": "Sorites problems"}, {"id": "37245085-bc8d-4cf2-9c94-37c7e8c5bf92", "type": "concept", "title": "Vagueness"}, {"id": "e8fa9dc5-9254-4f6a-acea-205326b0c4df", "type": "concept", "title": "Coincident objects"}, {"id": "3f6bc601-a0be-4f0a-b7f5-23192da092b5", "type": "concept", "title": "Statue and clay"}], "description": "Why it matters: Tables, statues, organisms, and artifacts raise puzzles about boundaries and persistence."}, {"id": "262584fa-671b-4864-ab4c-f93882a33a06", "type": "subtopic", "title": "Mereological structure", "children": [{"id": "b15c5a1e-17a7-4ccd-b46e-f325c5380005", "type": "concept", "title": "Proper parts"}, {"id": "0329a1f0-d3a1-4f7a-87d5-cfdf1947ec8e", "type": "concept", "title": "Fusion"}, {"id": "151aa792-ae63-4513-92de-822fbed1e01e", "type": "concept", "title": "Overlap"}, {"id": "93f89727-6f05-447e-bbcf-8d8b83d69dc8", "type": "concept", "title": "Atomism and gunk"}], "description": "Why it matters: Parts and wholes are central to metaphysics, science, and ordinary ontolog